import logging
import os


def get_execution_id(test_tags=None):
    """Get execution id - variable appended to CM test run like ute:id:1234-1"""
    if test_tags is None:
        logging.info("Tags not provided. Getting from robot 'TEST_TAGS' variable")
        test_tags = _get_tags_from_robot_variable()
    exec_id = _parse_execution_id(test_tags)
    if not exec_id:
        logging.info("Could not get test tags, last resort - trying to get from env variable")
        exec_id = _get_execution_id_from_env_var()
    return exec_id


def _parse_execution_id(test_tags):
    ute_id = "ute:id:"
    try:
        tag = next(tag for tag in test_tags if tag.startswith(ute_id))
        execution_id = tag.split(ute_id)[-1]
        logging.info('UTE testcase id: %s', execution_id)
        return execution_id
    except (StopIteration, KeyError):
        logging.info('UTE testcase id could not be parsed out of test tags.')
    except AttributeError:
        logging.error("ScoutAPI hasn't been setup yet.")


def _get_tags_from_robot_variable():
    tags = []
    try:
        from robot.libraries.BuiltIn import BuiltIn
        tags = BuiltIn().get_variable_value('${TEST_TAGS}', [])
    except Exception:
        logging.info("Tags cannot be obtained via 'TEST_TAGS' variable")
    return tags


def _get_execution_id_from_env_var():
    exec_id = os.getenv("CM_EXECUTION_ID")
    if exec_id:
        # id 1 is added since we dont know how many TCs are in the suite, thus it is better to settle with id 1 since
        # there must be at least one test in the suite
        exec_id = "{}-1".format(exec_id)
        logging.info("Execution if obtained from env variable: %s", exec_id)
    return exec_id
